function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu section is a <section class="page-section user-items-list-section">
  $('section.page-section.user-items-list-section').each((_, secEl) => {
    const $sec = $(secEl);
    const $list = $sec.find('.user-items-list');

    // Determine section title from data-current-context or fallback to heading
    let sectionTitle = null;
    const ctxAttr = $list.attr('data-current-context');
    if (ctxAttr) {
      try {
        const parsed = JSON.parse(ctxAttr);
        if (parsed && parsed.sectionTitle) {
          sectionTitle = cleanText(parsed.sectionTitle);
        }
      } catch (_) {}
    }
    if (!sectionTitle) {
      sectionTitle = cleanText($sec.find('.list-section-title strong').text()) || null;
    }

    // Process each list item (menu entry)
    $list.find('li.list-item').each((_, liEl) => {
      const $li = $(liEl);
      const $wrapper = $li.find('.list-item-content__text-wrapper');

      // Dish name (h2)
      const nameRaw = cleanText($wrapper.find('h2.list-item-content__title').text());
      if (!nameRaw) return;
      const name = nameRaw.replace(/^\d+\s*\.\s*/, ''); // strip leading numbers like "12. "

      // Description and price live in .list-item-content__description
      const $descBox = $wrapper.find('.list-item-content__description');
      let description = null;
      const $firstPara = $descBox.find('p').eq(0);
      if ($firstPara.length) {
        description = cleanText($firstPara.text());
      }

      // Price: look for <strong> inside a p (usually the second paragraph)
      let priceNum = null;
      const $priceStrong = $descBox.find('p strong');
      if ($priceStrong.length) {
        priceNum = parsePrice(cleanText($priceStrong.text()));
      }
      // Fallback: try to parse any price-like text in the description box
      if (priceNum === null) {
        priceNum = parsePrice(cleanText($descBox.text()));
      }

      // Dedup by section+name+description+price
      const key = `${sectionTitle || ''}|${name}|${description || ''}|${priceNum}`;
      if (!seen.has(key)) {
        seen.add(key);
        items.push({
          section: sectionTitle,
          name,
          description,
          price: priceNum
        });
      }
    });
  });

  return items;
}
```

